    auto ExpectedOpts = PassBuilder::parsePassParameters(PARSER, Name, NAME);  \
    if (!ExpectedOpts)                                                         \
      return ExpectedOpts.takeError();                                         \
    auto &&Opts = *ExpectedOpts;                                               \
    (void)Opts;                                                                \
    FPM.addPass(CREATE_PASS);                                                  \
    return true;                                                               \
  }

#include "PollyPasses.def"
  return false;
}

